#!/usr/bin/env bash
# Consulta read-only no Postgres de producao via Management API.
set +e

TOKEN="${SUPABASE_ACCESS_TOKEN:?}"
SB_URL="${SB_URL:?}"
REF="${SB_URL#https://}"
REF="${REF%%.supabase.co*}"
echo "== projeto: $REF =="

q() {
  local label="$1" sql="$2" body
  echo "===== $label ====="
  body=$(jq -nc --arg q "$sql" '{query:$q}')
  curl -s -X POST "https://api.supabase.com/v1/projects/$REF/database/query" \
    -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" \
    --data-binary "$body" | head -c 4000
  echo
}

q "Funcoes de picking no catalogo" "select p.proname, pg_get_function_identity_arguments(p.oid) as args, p.prosecdef as secdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('iniciar_tarefa_picking','concluir_tarefa_picking') order by 1"

q "EXECUTE por role nas RPCs de picking" "select has_function_privilege('anon','public.iniciar_tarefa_picking(uuid)','EXECUTE') as anon_iniciar, has_function_privilege('authenticated','public.iniciar_tarefa_picking(uuid)','EXECUTE') as auth_iniciar, has_function_privilege('anon','public.concluir_tarefa_picking(uuid,numeric,text)','EXECUTE') as anon_concluir, has_function_privilege('authenticated','public.concluir_tarefa_picking(uuid,numeric,text)','EXECUTE') as auth_concluir"

q "Superficie anon: funcoes publicas executaveis pela chave publica" "select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and has_function_privilege('anon', p.oid, 'EXECUTE') order by 1"

q "Tabelas chave: existe, RLS, policies" "select c.relname, c.relrowsecurity as rls, (select count(*) from pg_policies pol where pol.schemaname='public' and pol.tablename=c.relname) as policies from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('tarefas','system_settings','produtos','user_roles','estoque_posicoes') order by 1"

q "SELECT concedido a anon nas tabelas chave" "select c.relname, has_table_privilege('anon', c.oid, 'SELECT') as anon_select from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('tarefas','system_settings','produtos','user_roles','estoque_posicoes') order by 1"

q "Volumes" "select (select count(*) from public.system_settings) as system_settings, (select count(*) from public.tarefas) as tarefas, (select count(*) from public.user_roles where role='admin') as admins"

q "Migrations registradas no banco" "select count(*) as aplicadas from supabase_migrations.schema_migrations"

q "Ultimas migrations aplicadas" "select version from supabase_migrations.schema_migrations order by version desc limit 8"

q "Guardas internas das funcoes expostas a anon" "select p.proname, p.prosecdef as definer, (pg_get_functiondef(p.oid) like '%auth.uid()%') as checa_auth_uid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and has_function_privilege('anon', p.oid, 'EXECUTE') order by 1"

q "Funcoes citadas em policies de RLS" "select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and exists (select 1 from pg_policies pol where pol.schemaname='public' and ((coalesce(pol.qual,'') like '%'||p.proname||'%') or (coalesce(pol.with_check,'') like '%'||p.proname||'%'))) order by 1"

q "Policies das tabelas chave" "select tablename, policyname, cmd, coalesce(qual,'') as usando, coalesce(with_check,'') as com_check from pg_policies where schemaname='public' and tablename in ('tarefas','produtos','system_settings','user_roles') order by 1,2"
q "Policies (todos os schemas) que citam as funcoes candidatas" "select schemaname||'.'||tablename||' :: '||policyname as pol from pg_policies where coalesce(qual,'')||' '||coalesce(with_check,'') ~* 'iniciar_tarefa_picking|concluir_tarefa_picking|move_stock|aplicar_ajuste_estoque|log_audit_event|registrar_checkin_diario|collect_challenge_reward|adicionar_xp|descontar_pontos|get_current_user_permissions|get_dashboard_metrics|refresh_dashboard_materialized_views|incrementar_metrica_dashboard|attach_user_to_default_tenant|get_user_role|has_role_v2|get_min_stock_threshold|get_reorder_point'"

q "Views que citam as funcoes candidatas" "select schemaname||'.'||viewname as v from pg_views where definition ~* 'iniciar_tarefa_picking|concluir_tarefa_picking|move_stock|aplicar_ajuste_estoque|log_audit_event|registrar_checkin_diario|collect_challenge_reward|adicionar_xp|descontar_pontos|get_current_user_permissions|get_dashboard_metrics|refresh_dashboard_materialized_views|incrementar_metrica_dashboard|attach_user_to_default_tenant|get_user_role|has_role_v2|get_min_stock_threshold|get_reorder_point'"

q "Integridade: FKs de public sem indice de suporte" "select c.conrelid::regclass::text as tabela, c.conname, pg_get_constraintdef(c.oid) as definicao from pg_constraint c where c.contype='f' and c.connamespace='public'::regnamespace and not exists (select 1 from pg_index i where i.indrelid=c.conrelid and i.indisvalid and i.indpred is null and (i.indkey::smallint[])[0:array_length(c.conkey,1)-1] = c.conkey) order by 1,2"

q "Integridade: constraints de public nao validadas" "select conrelid::regclass::text as tabela, conname, contype, convalidated from pg_constraint where connamespace='public'::regnamespace and not convalidated order by 1,2"

q "Integridade: indices invalidos ou nao prontos" "select c.relname as tabela, i.indexrelid::regclass::text as indice, i.indisvalid, i.indisready from pg_index i join pg_class c on c.oid=i.indrelid where c.relnamespace='public'::regnamespace and (not i.indisvalid or not i.indisready) order by 1"

q "Integridade: indices duplicados (mesma tabela, colunas e operadores)" "select i.indrelid::regclass::text as tabela, string_agg(i.indexrelid::regclass::text || case when exists (select 1 from pg_constraint k where k.conindid = i.indexrelid) then ' [constraint]' else '' end || case when i.indisunique then ' [unique]' else '' end || ' scan=' || coalesce((select s.idx_scan from pg_stat_user_indexes s where s.indexrelid = i.indexrelid), 0) || ' ' || pg_size_pretty(pg_relation_size(i.indexrelid)), ' | ' order by i.indexrelid::regclass::text) as indices_sem_duplicata from pg_index i where i.indisvalid and i.indrelid in (select oid from pg_class where relnamespace='public'::regnamespace and relkind='r') group by i.indrelid, i.indkey, i.indclass, i.indoption, i.indpred having count(*) > 1 order by 1"

q "Integridade: tabelas de public sem PK" "select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not exists (select 1 from pg_constraint k where k.conrelid=c.oid and k.contype='p') order by 1"

q "Integridade: sequences acima de 50% do limite" "select schemaname||'.'||sequencename as seq, last_value, max_value, round(100.0*last_value/max_value,1) as pct from pg_sequences where max_value>0 and last_value is not null and last_value::numeric/max_value > 0.5 order by 4 desc limit 10"

q "Anon: funcoes que o predicado da 20261124120000 reprova (deve ser vazio)" "select coalesce(json_agg(p.oid::regprocedure::text order by 1), '[]'::json) as abertas from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prorettype <> 'pg_catalog.trigger'::regtype and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e') and has_function_privilege('anon', p.oid, 'EXECUTE') and p.proname <> all (array['has_role','is_tenant_admin','is_tenant_member','effective_tenant_id','default_tenant_id','current_tenant_id','check_login_lockout','record_failed_login','reset_login_attempts','get_backend_health'])"

q "XP: as 3 internas e descontar_pontos (anon, auth)" "select coalesce(json_agg(json_build_object('fn', p.proname, 'anon', has_function_privilege('anon', p.oid, 'EXECUTE'), 'auth', has_function_privilege('authenticated', p.oid, 'EXECUTE'), 'guardada', pg_get_functiondef(p.oid) like '%auth.uid()%') order by 1), '[]'::json) as xp from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('adicionar_xp','incrementar_metrica_dashboard','get_user_role','descontar_pontos','check_login_lockout','record_failed_login','reset_login_attempts')"

q "Funcoes que chamam as candidatas (nome, secdef, anon_exec)" "select n.nspname||'.'||p.proname||' definer='||p.prosecdef||' anon='||has_function_privilege('anon', p.oid, 'EXECUTE') as f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and p.prosrc ~* 'iniciar_tarefa_picking|concluir_tarefa_picking|move_stock|aplicar_ajuste_estoque|log_audit_event|registrar_checkin_diario|collect_challenge_reward|adicionar_xp|descontar_pontos|get_current_user_permissions|get_dashboard_metrics|refresh_dashboard_materialized_views|incrementar_metrica_dashboard|attach_user_to_default_tenant|get_user_role|has_role_v2|get_min_stock_threshold|get_reorder_point' and n.nspname not in ('pg_catalog','information_schema') order by 1"

q "Privilegio de authenticated nas candidatas (deve ser true)" "select count(*) filter (where has_function_privilege('authenticated', p.oid, 'EXECUTE')) as ok_auth, count(*) filter (where has_function_privilege('anon', p.oid, 'EXECUTE')) as ok_anon, count(*) as total from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname ~* '^(iniciar_tarefa_picking|concluir_tarefa_picking|move_stock|aplicar_ajuste_estoque|log_audit_event|registrar_checkin_diario|collect_challenge_reward|adicionar_xp|descontar_pontos|get_current_user_permissions|get_dashboard_metrics|refresh_dashboard_materialized_views|incrementar_metrica_dashboard|attach_user_to_default_tenant|get_user_role|has_role_v2|get_min_stock_threshold|get_reorder_point)\$'"
q "RLS 1: tabelas de public com RLS DESABILITADO" "select count(*) as total, string_agg(relname, ', ' order by relname) as nomes from (select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity) t"

q "RLS 2: tabelas com RLS ligado e ZERO policies" "select count(*) as total, string_agg(relname, ', ' order by relname) as nomes from (select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity and not exists (select 1 from pg_policies pol where pol.schemaname='public' and pol.tablename=c.relname)) t"

q "RLS 3: policies que liberam anon com USING true" "select count(*) as total, string_agg(tablename||' :: '||policyname||' ['||cmd||']', ' ;; ' order by tablename, policyname) as lista from (select tablename, policyname, cmd from pg_policies where schemaname='public' and 'anon'=any(roles) and (qual is null or btrim(lower(qual)) in ('true','(true)'))) t"

q "RLS 4: grants de ESCRITA para anon" "select count(*) as total, string_agg(relname||' -> '||privs, ' ;; ' order by relname) as lista from (select c.relname, string_agg(v.g, ',' order by v.g) as privs from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral (values ('INSERT'),('UPDATE'),('DELETE')) v(g) where n.nspname='public' and c.relkind='r' and has_table_privilege('anon', c.oid, v.g) group by 1) t"

q "RLS 5: views e matviews de public (security_invoker)" "select count(*) as total, string_agg(relname||'['||relkind::text||']'||case when inv=1 then ':invoker' else ':DONO' end, ' ;; ' order by relname) as lista from (select c.relname, c.relkind, case when coalesce(array_to_string(c.reloptions,','),'') like '%security_invoker=%true%' then 1 else 0 end as inv from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('v','m')) t(relname,relkind,inv)"

q "RLS 6: policies FOR ALL com roles public" "select count(*) as total, string_agg(tablename||' :: '||policyname, ' ;; ' order by tablename) as lista from (select tablename, policyname from pg_policies where schemaname='public' and 'public'=any(roles) and cmd='ALL') t"

q "MV 1: definicao das matviews (coluna tenant? tamanho?)" "select c.relname, length(pg_get_viewdef(c.oid,true)) as bytes, (pg_get_viewdef(c.oid,true) ~* 'tenant') as cita_tenant, (select count(*) from pg_attribute a where a.attrelid=c.oid and a.attname='tenant_id' and a.attnum>0 and not a.attisdropped) as col_tenant from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='m' order by 1"

q "MV 2: SELECT por role nas matviews" "select c.relname, has_table_privilege('anon',c.oid,'SELECT') as anon, has_table_privilege('authenticated',c.oid,'SELECT') as auth, has_table_privilege('service_role',c.oid,'SELECT') as svc from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='m' order by 1"

q "Funcoes SECURITY DEFINER sem search_path fixo" "select count(*) as total, string_agg(proname, ', ' order by proname) as nomes from (select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and (p.proconfig is null or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%'))) t"

q "Triggers desabilitados ou em estado parcial" "select count(*) as total, string_agg(relname||'.'||tgname||' ['||tgenabled::text||']', ', ' order by relname) as lista from (select c.relname, t.tgname, t.tgenabled from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgenabled <> 'O') t"
q "TEN 1: tenants em uso por tabela core" "select json_build_object('produtos',(select count(distinct tenant_id) from public.produtos),'tarefas',(select count(distinct tenant_id) from public.tarefas),'clientes',(select count(distinct tenant_id) from public.clientes),'armazens',(select count(distinct tenant_id) from public.armazens),'posicoes_estoque',(select count(distinct tenant_id) from public.posicoes_estoque),'pick_orders',(select count(distinct tenant_id) from public.pick_orders),'stock_movements',(select count(distinct tenant_id) from public.stock_movements),'audit_log',(select count(distinct tenant_id) from public.audit_log)) as r"
q "TEN 2: tabelas distintas com policy de predicado true" "select count(distinct tablename) as tabelas, coalesce(string_agg(distinct tablename, ', ' order by tablename), '-') as nomes from pg_policies where schemaname='public' and ((cmd in ('SELECT','DELETE','UPDATE','ALL') and btrim(coalesce(qual,'')) = 'true') or (cmd in ('INSERT','UPDATE','ALL') and btrim(coalesce(with_check,'')) = 'true'))"
q "TEN 3: tabelas distintas com tenant_id sem filtro de tenant na policy" "select count(distinct tablename) as tabelas, coalesce(string_agg(distinct tablename, ', ' order by tablename), '-') as nomes from pg_policies pol where pol.schemaname='public' and pol.cmd in ('SELECT','ALL') and coalesce(pol.qual,'') not like '%tenant%' and coalesce(pol.with_check,'') not like '%tenant%' and exists (select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=pol.tablename and col.column_name='tenant_id')"

q "TEN 4: tabelas com policy permissiva true - flags tem_tenant_id / tenant_isolation / cita_tenant" "select count(*) as total, string_agg(x, ' ' order by x) as mapa from (select p.tablename || ':' || case when exists(select 1 from information_schema.columns c where c.table_schema='public' and c.table_name=p.tablename and c.column_name='tenant_id') then 'T' else '-' end || case when count(*) filter (where p.policyname like '%tenant_isolation%') > 0 then 'ti' else '--' end || case when count(*) filter (where coalesce(p.qual,'')||coalesce(p.with_check,'') like '%tenant%') > 0 then 't' else '-' end as x from pg_policies p where p.schemaname='public' and (btrim(coalesce(p.qual,''))='true' or btrim(coalesce(p.with_check,''))='true') group by p.tablename) t"
q "TEN 5: tabelas com policy permissiva e NENHUMA outra policy que cita tenant - fechar equivale a regressao" "select count(*) as total, coalesce(string_agg(nome, ' ' order by nome), '-') as sem_filtro from (select p.tablename as nome, (select count(*) from pg_policies q where q.schemaname='public' and q.tablename=p.tablename and (coalesce(q.qual,'')||coalesce(q.with_check,'')) like '%tenant%') as outras from pg_policies p where p.schemaname='public' and (btrim(coalesce(p.qual,''))='true' or btrim(coalesce(p.with_check,''))='true') group by p.tablename) t where outras = 0"
q "TEN 6: como as policies que citam tenant sao escritas" "select policyname, cmd, roles::text as roles, coalesce(qual,'-') as usando, coalesce(with_check,'-') as com_check, tablename from pg_policies where schemaname='public' and (coalesce(qual,'')||coalesce(with_check,'')) like '%tenant%' order by tablename limit 3"
q "TEN 7: usuarios ativos e sem tenant definido" "select count(*) as total_roles, count(*) filter (where tenant_id is null) as sem_tenant from public.user_roles"
q "TEN 8: tenants distintos por tabela de public - prova de que o filtro nao perde linha" "with x as (select c.relname as t, btrim(array_to_string(xpath('//n_tenants/text()', query_to_xml('select count(distinct tenant_id)::text as n_tenants from public.\"' || c.relname || '\"', false, true, '')), ''))::int as n from pg_class c join pg_namespace ns on ns.oid=c.relnamespace where ns.nspname='public' and c.relkind='r' and exists (select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=c.relname and col.column_name='tenant_id')) select count(*) as tabelas, coalesce(max(n::int),0) as max_tenants, coalesce(string_agg(t || '=' || n, ' ' order by t) filter (where n::int > 1), '-') as multi from x"
q "ALVO 1: por que uma funcao com anon=true nao entra no predicado - retorno, trigger, extensao" "select p.proname, p.prokind, p.prorettype::regtype::text as retorno, p.prosecdef as secdef, (select count(*) from pg_depend d where d.objid=p.oid and d.deptype='e') as dep_ext, (select count(*) from pg_trigger t where t.tgfoid=p.oid) as em_trigger, has_function_privilege('anon', p.oid, 'EXECUTE') as anon, has_function_privilege('authenticated', p.oid, 'EXECUTE') as auth from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('aplicar_ajuste_estoque','attach_user_to_default_tenant','audit_sensitive_row_change','handle_new_user','increment_version','log_posicao_status_change','set_system_settings_updated_at','iniciar_tarefa_picking','concluir_tarefa_picking','move_stock') order by 1"
q "TEN 9: colunas tenant_id nullable ou sem default" "select count(*) as colunas, count(*) filter (where is_nullable='YES') as nullable, count(*) filter (where column_default is null) as sem_default from information_schema.columns where table_schema='public' and column_name='tenant_id'"
q "TEN 10: linhas com tenant_id nulo - visiveis para todos no predicado atual" "with x as (select c.relname as t, btrim(array_to_string(xpath('//n_null/text()', query_to_xml('select count(*) filter (where tenant_id is null)::text as n_null from public.\"' || c.relname || '\"', false, true, '')), ''))::int as n from pg_class c join pg_namespace ns on ns.oid=c.relnamespace where ns.nspname='public' and c.relkind='r' and exists (select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=c.relname and col.column_name='tenant_id')) select count(*) as tabelas, coalesce(sum(n),0) as linhas_sem_tenant, coalesce(string_agg(t || '=' || n, ' ' order by t) filter (where n > 0), '-') as orfas from x"

q "PERM 1: tenant_isolation e permissive ou restrictive" "select policyname, permissive, cmd, roles::text as roles from pg_policies where schemaname='public' and tablename='produtos' order by permissive, policyname"
q "PERM 2: tabelas cujas unicas policies PERMISSIVE sao as de predicado true - dropar fecharia a tabela" "select count(*) as tabelas_risco, coalesce(string_agg(tablename, ' ' order by tablename), '-') as nomes from (select tablename from pg_policies where schemaname='public' group by tablename having count(*) filter (where permissive='PERMISSIVE') > 0 and count(*) filter (where permissive='PERMISSIVE') = count(*) filter (where permissive='PERMISSIVE' and (btrim(coalesce(qual,''))='true' or btrim(coalesce(with_check,''))='true'))) t"
q "PERM 3: distribuicao permissive x restrictive em public" "select permissive, count(*) as policies, count(distinct tablename) as tabelas from pg_policies where schemaname='public' group by permissive order by 1"
q "PERM 4: roles das policies de predicado true" "select roles::text as roles, count(*) as policies, count(distinct tablename) as tabelas from pg_policies where schemaname='public' and (btrim(coalesce(qual,''))='true' or btrim(coalesce(with_check,''))='true') group by roles::text order by 2 desc"

q "TEN 11: coluna tenant_id SEM a policy tenant_isolation - fica fora do isolamento e do endurecimento" "select c.table_name, c.is_nullable, coalesce(c.column_default,'-') as padrao, (select count(*) from pg_policies p where p.schemaname='public' and p.tablename=c.table_name) as policies from information_schema.columns c where c.table_schema='public' and c.column_name='tenant_id' and not exists (select 1 from pg_policies t where t.schemaname='public' and t.tablename=c.table_name and t.policyname='tenant_isolation') order by c.table_name"
q "TEN 12: tabelas de public COM tenant_isolation e SEM coluna tenant_id - policy invalida" "select p.tablename from pg_policies p where p.schemaname='public' and p.policyname='tenant_isolation' and not exists (select 1 from information_schema.columns c where c.table_schema='public' and c.table_name=p.tablename and c.column_name='tenant_id') order by p.tablename"
q "VIEW 1: views de public sem security_invoker que leem tabela com RLS" "select count(*) as total, coalesce(string_agg(c.relname, ' ' order by c.relname), '-') as nomes from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind = 'v' and not exists (select 1 from unnest(coalesce(c.reloptions,'{}')) o where o like 'security_invoker=%on%' or o = 'security_invoker=true') and exists (select 1 from pg_rewrite r join pg_depend d on d.objid=r.oid join pg_class t on t.oid=d.refobjid join pg_namespace tn on tn.oid=t.relnamespace where r.ev_class=c.oid and tn.nspname='public' and t.relkind='r' and t.relrowsecurity)"
q "SEQ 1: sequences com grant para anon" "select count(*) as total, coalesce(string_agg(c.relname, ' ' order by c.relname), '-') as nomes from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S' and (has_sequence_privilege('anon', c.oid, 'USAGE') or has_sequence_privilege('anon', c.oid, 'SELECT') or has_sequence_privilege('anon', c.oid, 'UPDATE'))"
q "SEQ 2: sequences de public e dono" "select count(*) as total, count(*) filter (where pg_get_userbyid(c.relowner) <> 'postgres') as outro_dono from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S'"

q "RBAC 1: colunas reais de user_roles" "select column_name, data_type, is_nullable from information_schema.columns where table_schema='public' and table_name='user_roles' order by ordinal_position"
q "RBAC 2: vinculos e unidades em tenant_members" "select count(*) as vinculos, count(distinct tenant_id) as unidades, count(distinct user_id) as usuarios from public.tenant_members"
q "RBAC 3: policies de user_roles" "select policyname, permissive, cmd, roles::text as roles, coalesce(qual, '-') as qual from pg_policies where schemaname='public' and tablename='user_roles' order by policyname"
q "RBAC 4: policies de tenant_members" "select policyname, permissive, cmd, roles::text as roles, coalesce(qual, '-') as qual from pg_policies where schemaname='public' and tablename='tenant_members' order by policyname"
q "RBAC 5: linhas de user_roles por papel" "select count(*) as linhas, count(distinct tenant_id) as unidades, count(distinct user_id) as usuarios from public.user_roles"
q "RBAC 6: permissions cadastradas" "select (select count(*) from public.permissions) as permissions, (select count(*) from public.user_roles) as vinculos_papel"
q "TEN 13: valores distintos de default das colunas tenant_id" "select coalesce(column_default,'-') as padrao, count(*) as colunas from information_schema.columns where table_schema='public' and column_name='tenant_id' group by column_default order by 2 desc"

q "RBAC 7: usuarios sem papel atribuido" "select (select count(*) from auth.users) as usuarios, (select count(*) from public.user_roles) as com_papel, (select count(*) from auth.users u where not exists (select 1 from public.user_roles ur where ur.user_id = u.id)) as sem_papel, coalesce((select string_agg(distinct split_part(u.email, '@', 2), ' ') from auth.users u where not exists (select 1 from public.user_roles ur where ur.user_id = u.id)), '-') as dominios"
q "RBAC 8: papeis atribuidos" "select role::text as papel, count(*) as quantos from public.user_roles group by role order by 2 desc"
q "RBAC 9: usuarios sem vinculo de unidade" "select count(*) as sem_vinculo from auth.users u where not exists (select 1 from public.tenant_members tm where tm.user_id = u.id)"

q "RBAC 10: quando o usuario sem papel foi criado, quando logou e se confirmou email" "select u.created_at::date as criado, u.last_sign_in_at::date as ultimo_login, (u.email_confirmed_at is not null) as confirmado from auth.users u where not exists (select 1 from public.user_roles ur where ur.user_id = u.id)"

q "SYNC 1: quantos SKUs existem em produtos e o cursor da replicacao" "select (select count(*) from public.produtos) as n_produtos, (select count(*) from public.produtos_sync_estado) as n_estado"
q "SYNC 2: estado do cursor de sync" "select origem_atualizada_ate as cursor_ate, origem_sku as cursor_sku, ultima_execucao as ultima, ultimo_resultado as resultado, ultima_duracao_ms as ms from public.produtos_sync_estado"

q "RLS 7: policies de public com predicado literalmente true" "select count(*) as total, string_agg(tablename||' :: '||policyname||' ['||cmd||']', ' ;; ' order by tablename) as lista from pg_policies where schemaname='public' and ((cmd in ('SELECT','DELETE','UPDATE','ALL') and btrim(coalesce(qual,'')) = 'true') or (cmd in ('INSERT','UPDATE','ALL') and btrim(coalesce(with_check,'')) = 'true'))"
q "RLS 8: tabelas com tenant_id cuja policy nao filtra tenant" "select count(*) as total, string_agg(tablename||' :: '||policyname||' ['||cmd||']', ' ;; ' order by tablename) as lista from pg_policies pol where pol.schemaname='public' and pol.cmd in ('SELECT','ALL') and coalesce(pol.qual,'') not like '%tenant%' and coalesce(pol.with_check,'') not like '%tenant%' and exists (select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=pol.tablename and col.column_name='tenant_id')"

q "CRON 1: jobs agendados (ativo, timeout explicito, frequencia, o que roda)" "select jobid, schedule, active, (command like '%timeout_milliseconds := 120000%') as timeout_120, left(replace(command, chr(10), ' '), 200) as comando from cron.job order by jobid"
q "CRON 2: execucoes das ultimas 48h (por job, com falhas)" "select jobid, count(*) as execucoes, count(*) filter (where status <> 'succeeded') as falhas, max(start_time)::timestamp(0) as ultima from cron.job_run_details where start_time > now() - interval '48 hours' group by jobid order by 3 desc, 1"
q "CRON 3: jobs ativos que nao rodaram nas ultimas 24h" "select j.jobid, j.schedule, left(replace(j.command, chr(10), ' '), 90) as comando from cron.job j where j.active and not exists (select 1 from cron.job_run_details r where r.jobid = j.jobid and r.start_time > now() - interval '24 hours') order by 1"
q "CRON 4: historico por job e database (inclui ids ja removidos)" "select d.database, d.jobid, min(d.start_time)::timestamp(0) as primeira, max(d.start_time)::timestamp(0) as ultima, count(*) as total, count(*) filter (where d.status <> 'succeeded') as falhas, (j.jobid is not null) as ainda_em_cron_job, coalesce(j.active, false) as ativo from cron.job_run_details d left join cron.job j on j.jobid = d.jobid and j.database = d.database group by d.database, d.jobid, j.jobid, j.active order by d.database, d.jobid"
q "CRON 5: agora, database atual e quantos jobs existem aqui" "select now()::timestamp(0) as agora_utc, current_database() as db, (select count(*) from cron.job) as jobs_neste_db, (select count(*) from cron.job where active) as ativos_neste_db"
q "HTTP 1: ultimas respostas do pg_net (status real da edge)" "select id, status_code, timed_out, coalesce(error_msg, '-') as erro, left(coalesce(content, ''), 110) as corpo, created::timestamp(0) as criado from net._http_response order by id desc limit 12"
q "HTTP 2: distribuicao de status das edges chamadas pelo cron nas ultimas 24h" "select coalesce(status_code::text, 'sem-resposta') as status, count(*) as quantas, max(created)::timestamp(0) as ultima from net._http_response where created > now() - interval '24 hours' group by 1 order by 2 desc"
q "HTTP 3: todas as respostas de 24h (para separar cron agendado de disparo manual)" "select id, coalesce(status_code::text, 'sem-resposta') as status, left(coalesce(content, ''), 70) as corpo, created::timestamp(0) as criado from net._http_response where created > now() - interval '24 hours' order by id"

q "SEC 1: grants de negocio executaveis pela chave publica (com corpo defensivo)" "select p.proname, pg_get_function_identity_arguments(p.oid) as args, p.prosecdef as secdef, has_function_privilege('anon', p.oid, 'EXECUTE') as anon, has_function_privilege('authenticated', p.oid, 'EXECUTE') as auth, coalesce(array_to_string(p.proconfig, ','), '-') as config from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('aplicar_ajuste_estoque','adicionar_xp','descontar_pontos','attach_user_to_default_tenant','get_backend_health') order by 1"
q "SEC 2: policies das tabelas de credencial e de config, com role e predicado" "select tablename, policyname, roles::text as roles, cmd, coalesce(qual, '-') as qual, coalesce(with_check, '-') as with_check from pg_policies where schemaname = 'public' and tablename in ('passkey_credentials','webauthn_challenges','system_settings','produtos_sync_estado') order by 1, 2"
q "SEC 3: privilegios de tabela por role nas tabelas sensiveis" "select c.relname, c.relrowsecurity as rls, has_table_privilege('anon', c.oid, 'SELECT') as anon_sel, has_table_privilege('anon', c.oid, 'INSERT') as anon_ins, has_table_privilege('anon', c.oid, 'UPDATE') as anon_upd, has_table_privilege('anon', c.oid, 'DELETE') as anon_del, has_table_privilege('authenticated', c.oid, 'SELECT') as auth_sel, has_table_privilege('authenticated', c.oid, 'INSERT') as auth_ins from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and c.relname in ('passkey_credentials','webauthn_challenges','system_settings','produtos_sync_estado','produtos') order by 1"
